      "text": "Sarvottam Cables Ltd is a manufacturer of power cables, wires and conductors.",
      "citations": ["S3"],
      "evidence": [{"id":"S3:E1"}]
    },
    {
      "text": "Revenue from operations for the quarter ended 30 June 2026 was ₹1,248 crore, up 18.0% year‑on‑year.",
      "citations": ["S3"],
      "evidence": [{"id":"S3:E3"}]
    },
    {
      "text": "Profit after tax for the quarter was ₹82 crore, a 5.9% increase from the prior year.",
      "citations": ["S3"],
      "evidence": [{"id":"S3:E6"}]
    },
    {
      "text": "EBITDA margin fell to 11.2%, down 170 basis points from 12.9% a year earlier.",
      "citations": ["S3"],
      "evidence": [{"id":"S3:E5"}]
    }
  ],
  "Bull case": [
    {
      "text": "The company says the new Bharuch plant will add about 30% to cable capacity and start commercial production in Q3 FY27.",
      "citations": ["S3"],
      "evidence": [{"id":"S3:E9"}]
    },
    {
      "text": "The company says its order book rose to ₹3,900 crore as of 30 June 2026, up from ₹3,150 crore a year ago.",
      "citations": ["S3"],
      "evidence": [{"id":"S3:E7"}]
    }
  ],
  "Bear case": [
    {
      "text": "Operating margins contracted by 170 basis points to 11.2% as copper prices rose sharply.",
      "citations": ["S1"],
      "evidence": [{"id":"S1:E3"}]
    },
    {
      "text": "Receivable days increased from 78 to 96 over the last year, driven by slower payments from large state utilities.",
      "citations": ["S2"],
      "evidence": [{"id":"S2:E5"}]
    },
    {
      "text": "The company received a statutory demand of ₹46.3 crore and intends to file an appeal, stating it does not expect material impact.",
      "citations": ["S7"],
      "evidence": [{"id":"S7:E1"},{"id":"S7:E2"}]
    }
  ],
